-- Borrowing records. Loan period 14 days. returned_days_ago NULL = still on loan.
INSERT INTO BOOK_ISSUES (member_id, book_id, issue_date, due_date, return_date)
SELECT m.member_id, b.book_id,
       CURRENT_DATE - v.issued_days_ago,
       CURRENT_DATE - v.issued_days_ago + 14,
       CASE WHEN v.returned_days_ago IS NULL THEN NULL
            ELSE CURRENT_DATE - v.returned_days_ago END
FROM (VALUES
  -- returned on time
  ('arjun.kumar@college.example',   'Database System Concepts',                  90, 80),
  ('divya.menon@college.example',   'Python Crash Course',                       75, 65),
  ('karthik.rao@college.example',   'Introduction to Algorithms',                70, 60),
  ('sneha.iyer@college.example',    'Discrete Mathematics and Its Applications', 55, 45),
  ('rahul.sharma@college.example',  'Operating System Concepts',                 50, 40),
  ('arjun.kumar@college.example',   'Python Crash Course',                       45, 38),
  ('priya.nair@college.example',    'Database System Concepts',                  40, 30),
  ('divya.menon@college.example',   'Malgudi Days',                              35, 25),
  -- returned late (a fine is created below)
  ('karthik.rao@college.example',   'Computer Networks',                         80, 57),
  ('sneha.iyer@college.example',    'Fundamentals of Database Systems',          60, 35),
  ('rahul.sharma@college.example',  'Wings of Fire',                             50, 31),
  ('faizan.ahmed@college.example',  'Concepts of Physics',                       42, 20),
  ('lakshmi.n@college.example',     'Introduction to Linear Algebra',            30, 10),
  -- on loan, not yet due
  ('arjun.kumar@college.example',   'Operating System Concepts',                  5, NULL),
  ('divya.menon@college.example',   'Introduction to Algorithms',                 3, NULL),
  ('priya.nair@college.example',    'Atomic Habits',                              8, NULL),
  ('faizan.ahmed@college.example',  'Clean Code',                                 2, NULL),
  -- on loan and overdue
  ('karthik.rao@college.example',   'Database System Concepts',                  25, NULL),
  ('sneha.iyer@college.example',    'Train to Pakistan',                         20, NULL),
  ('lakshmi.n@college.example',     'Fundamentals of Physics',                   18, NULL),
  ('rahul.sharma@college.example',  'Computer Networks',                         30, NULL)
) AS v(email, title, issued_days_ago, returned_days_ago)
JOIN MEMBERS m ON m.email = v.email
JOIN BOOKS   b ON b.title = v.title;

-- Fines for every late return at Rs. 2.00 per overdue day.
-- paid = amount already collected by the librarian (0 = unpaid).
INSERT INTO FINES (issue_id, amount, amount_paid, status, created_at)
SELECT i.issue_id,
       (i.return_date - i.due_date) * 2.00,
       COALESCE(p.paid, 0),
       CASE WHEN COALESCE(p.paid, 0) = 0 THEN 'Unpaid'
            WHEN COALESCE(p.paid, 0) < (i.return_date - i.due_date) * 2.00 THEN 'Partial'
            ELSE 'Paid' END,
       i.return_date + TIME '10:30'
FROM BOOK_ISSUES i
INNER JOIN MEMBERS m ON m.member_id = i.member_id
INNER JOIN BOOKS   b ON b.book_id   = i.book_id
LEFT JOIN (VALUES
  ('karthik.rao@college.example',  'Computer Networks',               18.00),
  ('sneha.iyer@college.example',   'Fundamentals of Database Systems', 10.00),
  ('faizan.ahmed@college.example', 'Concepts of Physics',             16.00)
) AS p(email, title, paid) ON p.email = m.email AND p.title = b.title
WHERE i.return_date > i.due_date;

INSERT INTO BOOK_REVIEWS (member_id, book_id, rating, review_text, review_date)
SELECT m.member_id, b.book_id, v.rating, v.review_text, CURRENT_DATE - v.days_ago
FROM (VALUES
  ('arjun.kumar@college.example',  'Database System Concepts',                  5, 'Clear chapters on ER modelling, SQL and normalization.', 78),
  ('priya.nair@college.example',   'Database System Concepts',                  4, 'Thorough, though some chapters are dense.',              29),
  ('divya.menon@college.example',  'Python Crash Course',                       4, 'Good practical projects for beginners.',                 64),
  ('karthik.rao@college.example',  'Introduction to Algorithms',                5, 'The standard reference for algorithm analysis.',         58),
  ('sneha.iyer@college.example',   'Discrete Mathematics and Its Applications', 4, 'Plenty of worked examples.',                             44),
  ('rahul.sharma@college.example', 'Operating System Concepts',                 3, 'Useful but long.',                                       39),
  ('divya.menon@college.example',  'Malgudi Days',                              5, 'Gentle, memorable stories.',                             24),
  ('karthik.rao@college.example',  'Computer Networks',                         3, 'Good layering explanations; dated in places.',           55),
  ('sneha.iyer@college.example',   'Fundamentals of Database Systems',          4, 'Strong coverage of relational algebra.',                 34),
  ('faizan.ahmed@college.example', 'Concepts of Physics',                       4, 'Good problem sets.',                                     19),
  ('rahul.sharma@college.example', 'Wings of Fire',                             5, 'Inspiring and easy to read.',                            30)
) AS v(email, title, rating, review_text, days_ago)
JOIN MEMBERS m ON m.email = v.email
JOIN BOOKS   b ON b.title = v.title;
